INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at) VALUES ('cmt_zom237_1', 'ZOM-237', 'usr_65c76e0b87aa7e9b', NULL, 'Tested on Android Submission #133 / iOS #49: opened a 10-card pack from the shop. On the second card the red NEW banner was already visible when the card flipped and then replayed its pop-in; the banner SFX fired on the 4th and 7th cards where no banner was shown. No effect on claiming the cards.', false, '2025-09-29T09:05:00Z', '2025-09-29T09:05:00Z');
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at) VALUES ('cmt_zom348_1', 'ZOM-348', 'usr_65c76e0b87aa7e9b', NULL, 'Tested on Android Submission #133 / iOS #49: the 1000-coin common pack showed no discount ribbon, the 80-bone pack showed none either, and the catapult offer showed -25% against a 100-gem list price. Tapping buy opened the store sheet with the price that was shown and the purchase went through.', false, '2025-09-29T09:50:00Z', '2025-09-29T09:50:00Z');
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at) VALUES ('cmt_zom438_1', 'ZOM-438', 'usr_65c76e0b87aa7e9b', NULL, 'Ran C_0120 five times on Android #133 / iOS #49. Monster count at level end was 12, 13, 11, 14, 12; the missing zombies never appeared, but the level still completed normally every run.', false, '2025-09-29T10:20:00Z', '2025-09-29T10:20:00Z');
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at) VALUES ('cmt_zom443_1', 'ZOM-443', 'usr_65c76e0b87aa7e9b', NULL, 'On a win-streak bonus level (#133 / #49) the removed items came from the same three columns on four streaks in a row, while an off-streak level removed a mixed set. Play continued normally.', false, '2025-09-29T10:45:00Z', '2025-09-29T10:45:00Z');
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at) VALUES ('cmt_zom449_1', 'ZOM-449', 'usr_fc22d5941b2aeb5c', NULL, 'Android Submission #133 on a low-end Android device: cold start into level 3, the tutorial highlight drew over the loading screen before the board appeared and the device stopped responding to taps for about 40 seconds; force-quit and relaunch got past it. MF11 microwave and MF12 controller still render with missing surfaces.', false, '2025-09-29T09:15:00Z', '2025-09-29T09:15:00Z');
