INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at) VALUES ('cmt_zom481_1', 'ZOM-481', 'usr_65c76e0b87aa7e9b', NULL, 'At 120 CPM on #133 / #49 the health bar stayed about a second after the death animation, then disappeared. Nothing else was affected, the board cleared and the level finished.', false, '2025-09-29T11:30:00Z', '2025-09-29T11:30:00Z');
