INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at) VALUES ('cmt_zom505_1', 'ZOM-505', 'usr_65c76e0b87aa7e9b', NULL, 'Android Submission #133: failed level 19 three times on purpose. Each retry reopened the tutorial panel over the pre-level screen; after tapping through all four steps the level started and could be played and finished. Same on a second install, never a case where the level couldn''t start.', false, '2025-09-29T12:40:00Z', '2025-09-29T12:40:00Z');
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at) VALUES ('cmt_zom534_1', 'ZOM-534', 'usr_65c76e0b87aa7e9b', NULL, '#133 / #49 against prod: completed the daily quest and stayed in the quest panel; the points stayed at 5/5 and the chest stayed locked until the app was force-quit and reopened, then it reset. No quest rewards were lost.', false, '2025-09-29T13:10:00Z', '2025-09-29T13:10:00Z');
