INSERT INTO gsheets.sheets_sheets (spreadsheet_id, sheet_id, title, "index", row_count, column_count, grid_json) VALUES ('f_0ebfccf33076f9dbf086bc', 0, 'How we gate', 0, 20, 7, '[["How we gate (ZM store submissions) - from the next gate on, updated Sep 23 after Leonard''s rules"],["One tab per gate, named after the candidate builds. One row per ticket."],[""],["Columns","ticket","title","build status","QA result","call","evidence"],["call","BLOCKER","KNOWN ISSUE","FIXED","NO CALL"],["build status","in candidate","not in candidate","server - live","server - not live","n/a"],["build status means (a server-side fix always takes a server value)","a bug QA re-tested on the candidates and saw working or couldn''t reproduce, or a Done bug whose fix was on main at the job''s Started line, even if the re-test still shows the bug (if nothing shows when the fix landed, go by when the ticket was closed)","a Done bug whose fix landed after the Started line","a server-side fix that''s fully on prod, including any migration or data it needs","a server-side fix with any part not on prod yet, even if its code is deployed","everything else: open bugs that still show up or nobody re-tested, no-call tickets"],["evidence","id or link of the record that decides the row"]]');
INSERT INTO gsheets.sheets_sheets (spreadsheet_id, sheet_id, title, "index", row_count, column_count, grid_json) VALUES ('f_0ebfccf33076f9dbf086bc', 1, 'Sep 22 - Android #127 / iOS #40', 1, 20, 6, '[["ticket","title","build status","QA result","call","evidence"],["ZOM-546","Bug: refill algorithm spawns fewer items over time","n/a","repro on #127","BLOCKER","ZOM-546"],["ZOM-559","Homing out on android(samsung), sound disappears.","n/a","not reproduced on #127 (Pixel)","KNOWN ISSUE","ZOM-559"],["ZOM-534","Quest points not resetting until app restart in production","n/a","seen on prod","KNOWN ISSUE","ZOM-534"],["ZOM-520","First loss as level doesn''t reset win streak","n/a","repro on #127","KNOWN ISSUE","ZOM-520"],["ZOM-535","Fast matching might target an already-dead zombie","n/a","repro on #127","KNOWN ISSUE","ZOM-535"],["ZOM-517","Monster loses enrage during item refill in endless mode","n/a","repro on #127","KNOWN ISSUE","ZOM-517"],["ZOM-429","Leaderboard next session doesn''t start without killing the app","n/a","repro on #40","KNOWN ISSUE","ZOM-429"],["ZOM-503","Giving lives in teams are unresponsive","in candidate","pass on #127","FIXED","match3d#422"]]');
